overpass_query:
[out:json][timeout:180];
area["ISO3166-1"="IN"][admin_level=2]->.a;
(
  // Common station tags
  node(area.a)[railway~"^(station|halt|stop)$"][station~"^(subway|light_rail)$"];
  way(area.a)[railway~"^(station|halt|stop)$"][station~"^(subway|light_rail)$"];
  relation(area.a)[railway~"^(station|halt|stop)$"][station~"^(subway|light_rail)$"];

  // Public transport tagging patterns
  node(area.a)[public_transport="station"][subway=yes];
  way(area.a)[public_transport="station"][subway=yes];
  relation(area.a)[public_transport="station"][subway=yes];

  node(area.a)[public_transport="station"][light_rail=yes];
  way(area.a)[public_transport="station"][light_rail=yes];
  relation(area.a)[public_transport="station"][light_rail=yes];

  // Some mappers use metro=yes
  node(area.a)[public_transport="station"][metro=yes];
  way(area.a)[public_transport="station"][metro=yes];
  relation(area.a)[public_transport="station"][metro=yes];
);
// Ensure ways/relations include a computed center.
out tags center;
